import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String str = scanner.nextLine();
        StringBuilder ans = new StringBuilder();
        boolean taken = false;
        int i = 0;
        while (i < str.length()) {
            char currentChar = str.charAt(i);
            if (currentChar != 'a' && currentChar != 'd') {
                ans.append(currentChar);
                i++;
                continue;
            }
            if (currentChar == 'a') {
                if (i == str.length() - 1 || str.charAt(i + 1) != 't' || ans.length() == 0 || taken) {
                    ans.append(currentChar);
                    i++;
                    continue;
                }
                taken = true;
                ans.append('@');
                i += 2;
                continue;
            }
            // currentChar == 'd'
            if (i >= str.length() - 3 || !(str.charAt(i + 1) == 'o' && str.charAt(i + 2) == 't') || ans.length() == 0) {
                ans.append(currentChar);
                i++;
                continue;
            }
            ans.append('.');
            i += 3;
        }
        System.out.println(ans.toString());
        scanner.close();
    }
}
